import 'package:flutter/material.dart'; import 'models/focus_session.dart'; import 'models/stage7.dart'; import 'services/stage7_storage.dart';
class AchievementsPage extends StatefulWidget { final List<FocusSession> sessions; const AchievementsPage({super.key, required this.sessions}); @override State<AchievementsPage> createState() => _AchievementsPageState(); }
class _AchievementsPageState extends State<AchievementsPage> { Map<String, DateTime> unlocked = {}; bool loading = true; @override void initState() { super.initState(); Stage7Storage().evaluate(widget.sessions).then((v) { if (mounted) setState(() { unlocked = v; loading = false; }); }); } @override Widget build(BuildContext context) { if (loading) return const Center(child: CircularProgressIndicator()); return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('Achievements', style: TextStyle(fontSize: 30, fontWeight: FontWeight.w800)), const SizedBox(height: 8), Text('${unlocked.length} / ${achievements.length} unlocked · Keep showing up for yourself.'), const SizedBox(height: 24), GridView.builder(shrinkWrap: true, physics: const NeverScrollableScrollPhysics(), gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent: 300, mainAxisExtent: 190, crossAxisSpacing: 16, mainAxisSpacing: 16), itemCount: achievements.length, itemBuilder: (_, i) { final a = achievements[i], date = unlocked[a.id]; return Card(child: Padding(padding: const EdgeInsets.all(18), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Icon(date == null ? Icons.lock_outline : Icons.emoji_events, color: date == null ? Colors.grey : const Color(0xFF7C5CFC), size: 34), const SizedBox(height: 10), Text(a.title, style: const TextStyle(fontWeight: FontWeight.w800)), const SizedBox(height: 4), Text(a.description, style: const TextStyle(color: Colors.grey)), const Spacer(), Text(date == null ? '🔒 ${a.requirement}' : '✓ Unlocked ${date.month}/${date.day}/${date.year}', style: TextStyle(color: date == null ? Colors.grey : const Color(0xFF7C5CFC), fontWeight: FontWeight.w600))]))); })]); } }
